/**
 * Backlog 8 (B group), P11 (docs/reviews/m2-2/response-r1.md): src/cli.ts readVersion() answered "0.0.0" for a package.json that cannot be
 * read, and also when it had no version, so `aiqh --version`, the `tool.version` of the verify report and the "Generated by" line of the
 * review packet named a tool version that was made up (and a version that is not a string went through as it was). The version is the
 * identity of the tool that made the evidence: when it cannot be read it is an error (exit 2, one line on standard error), not a default.
 * The real CLI is run as a child process from a copy of src/ in a temporary directory, so that `../package.json` is the copy's own file;
 * node_modules is a link to the repository's. A package.json that is not valid JSON is not tested: Node itself stops before aiqh runs.
 * The permission case is skipped for root. A correct package.json is the control: it passes before and after.
 */
import { spawnSync } from "node:child_process";
import { chmodSync, cpSync, existsSync, mkdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import path from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { makeTempDir, nodeEval } from "./helpers.ts";

const isRoot = typeof process.getuid === "function" && process.getuid() === 0;
const REPO_ROOT = path.resolve(import.meta.dirname, "..");
let appDir = "";
let cli = "";
let cleanup: () => void = () => {};

beforeAll(() => {
  const t = makeTempDir("aiqh-b8b-p11-");
  cleanup = t.cleanup;
  appDir = path.join(t.dir, "app");
  mkdirSync(appDir);
  cpSync(path.join(REPO_ROOT, "src"), path.join(appDir, "src"), { recursive: true });
  symlinkSync(path.join(REPO_ROOT, "node_modules"), path.join(appDir, "node_modules"));
  cli = path.join(appDir, "src", "cli.ts");
});
afterAll(() => {
  try {
    chmodSync(path.join(appDir, "package.json"), 0o644);
  } catch {
    // no package.json
  }
  cleanup();
});

function setPackageJson(text: string | null): void {
  const file = path.join(appDir, "package.json");
  try {
    chmodSync(file, 0o644);
  } catch {
    // no file yet
  }
  rmSync(file, { force: true });
  if (text !== null) writeFileSync(file, text);
}

function run(args: string[], cwd: string = appDir): { code: number | null; out: string; err: string } {
  const r = spawnSync(process.execPath, [cli, ...args], { cwd, encoding: "utf8", timeout: 30_000, killSignal: "SIGKILL" });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

const pkg = (version: unknown): string => JSON.stringify({ type: "module", ...(version === undefined ? {} : { version }) });

describe("backlog 8 P11: a version that cannot be read is an error, not '0.0.0'", () => {
  it("package.json does not exist (ENOENT): exit 2, nothing on standard output, the reason on standard error", () => {
    setPackageJson(null);
    const r = run(["--version"]);
    expect(r.code, r.err).toBe(2);
    expect(r.out).toBe("");
    expect(r.err).toMatch(/aiqh: unexpected error: cannot read the version from package\.json \(ENOENT\)/);
  });

  it.skipIf(isRoot)("package.json cannot be read (EACCES): exit 2", () => {
    setPackageJson(pkg("1.2.3"));
    chmodSync(path.join(appDir, "package.json"), 0o000);
    const r = run(["--version"]);
    chmodSync(path.join(appDir, "package.json"), 0o644);
    expect(r.code, r.err).toBe(2);
    expect(r.out).toBe("");
    expect(r.err).toMatch(/cannot read the version from package\.json \(EACCES\)/);
  });

  it.each([
    ["has no version", undefined],
    ["has a version that is a number", 123],
    ["has an empty version", ""],
    ["has a version that is null", null],
  ])("package.json %s: exit 2, never printed as a version", (_name, version) => {
    setPackageJson(pkg(version));
    const r = run(["--version"]);
    expect(r.code, r.err).toBe(2);
    expect(r.out).toBe("");
    expect(r.err).toMatch(/package\.json has no version string/);
  });

  it("verify does not run, and no report is written, when the version cannot be read", () => {
    setPackageJson(null);
    const t = makeTempDir("aiqh-b8b-p11-proj-");
    try {
      writeFileSync(path.join(t.dir, "aiqh.config.jsonc"), JSON.stringify({ version: 1, project: { name: "p" }, checks: [{ name: "a", kind: "lint", command: nodeEval("process.exit(0)") }] }));
      const r = run(["verify", "--config", path.join(t.dir, "aiqh.config.jsonc")], t.dir);
      expect(r.code, r.err).toBe(2);
      expect(existsSync(path.join(t.dir, "artifacts", "verification", "latest.json"))).toBe(false);
    } finally {
      t.cleanup();
    }
  });
});

describe("backlog 8 P11 controls (pass before and after)", () => {
  it("a package.json with a version string: --version prints it, exit 0", () => {
    setPackageJson(pkg("9.8.7"));
    const r = run(["--version"]);
    expect(r.code, r.err).toBe(0);
    expect(r.out.trim()).toBe("9.8.7");
    expect(r.err).toBe("");
  });

  it("verify records the version of the package.json it was started with in the report", () => {
    setPackageJson(pkg("9.8.7"));
    const t = makeTempDir("aiqh-b8b-p11-proj-");
    try {
      writeFileSync(path.join(t.dir, "aiqh.config.jsonc"), JSON.stringify({ version: 1, project: { name: "p" }, checks: [{ name: "a", kind: "lint", command: nodeEval("process.exit(0)") }] }));
      const r = run(["verify", "--config", path.join(t.dir, "aiqh.config.jsonc")], t.dir);
      expect(r.code, r.err).toBe(0);
      const report = JSON.parse(readFileSync(path.join(t.dir, "artifacts", "verification", "latest.json"), "utf8")) as { tool: { version: string } };
      expect(report.tool.version).toBe("9.8.7");
    } finally {
      t.cleanup();
    }
  });
});
